package com.campusvibe.controller;
import com.campusvibe.entity.*; import com.campusvibe.repository.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*; import java.time.*;
@RestController @RequestMapping("/api/registrations") public class RegistrationController {final RegistrationRepository regs;final UserRepository users;final EventRepository events;public RegistrationController(RegistrationRepository r,UserRepository u,EventRepository e){regs=r;users=u;events=e;}
@GetMapping @PreAuthorize("hasAnyRole('ADMIN','COORDINATOR','JUDGE')") public List<Registration> all(){return regs.findAll();}
@GetMapping("/student/{id}") public List<Registration> student(@PathVariable Long id){return regs.findByStudentId(id);}
@PostMapping @PreAuthorize("hasRole('STUDENT')") public Registration create(@RequestBody Map<String,Object> b){Long sid=Long.valueOf(b.get("studentId").toString()),eid=Long.valueOf(b.get("eventId").toString());if(regs.existsByStudentIdAndEventId(sid,eid))throw new IllegalArgumentException("Already registered");Registration r=new Registration();r.student=users.findById(sid).orElseThrow();r.event=events.findById(eid).orElseThrow();r.registrationCode="CV26-"+UUID.randomUUID().toString().substring(0,8).toUpperCase();return regs.save(r);}
@PutMapping("/{id}/status") @PreAuthorize("hasAnyRole('ADMIN','COORDINATOR')") public Registration status(@PathVariable Long id,@RequestParam RegistrationStatus status){Registration r=regs.findById(id).orElseThrow();r.status=status;return regs.save(r);} @DeleteMapping("/{id}") @PreAuthorize("hasRole('STUDENT')") public void cancel(@PathVariable Long id){Registration r=regs.findById(id).orElseThrow();r.status=RegistrationStatus.CANCELLED;regs.save(r);}}
